## Physical current solid: the reachable band is the actual WoodCuts cells (including untouched
## full slices); outside it the analytic stem. Partial slices are clipped at a/b, so any partition
## is additive. This is current geometry, never initial minus historical outputs.
static func stock_volume(t: ChopTree, a: float, b: float) -> float:
	a = clampf(a, 0.0, t.tree_height)
	b = clampf(b, a, t.tree_height)
	var w := t.wood_model()
	var lo := maxf(a, w.y0)
	var hi := minf(b, w.y1)
	var out := envelope_volume(t, a, minf(b, w.y0)) + envelope_volume(t, maxf(a, w.y1), b)
	if hi <= lo:
		return envelope_volume(t, a, b)
	for i in range(maxi(w.slice_of(lo), 0), mini(w.slice_of(hi) + 1, w.slices)):
		var y := w.y0 + i * WoodCuts.DZ
		var dy := maxf(minf(hi, y + WoodCuts.DZ) - maxf(lo, y), 0.0)
		out += w.area_of(i) * dy
	return out


## Vertical cross-sections of the drawn standing solid; pole = actual cylinder. The lean shears
## the original mesh, so it cannot create volume through a later change of cut_h()/log stretch.
static func envelope_volume(t: ChopTree, a: float, b: float) -> float:
	if b <= a:
		return 0.0
	if t.pole:
		return PI * t.radius() * t.radius() * (b - a)
	var k := t.bark_radius(0.0) / (1.0 + FLARE_K)
	return PI * k * k * (_g(t.tree_height, b) - _g(t.tree_height, a))
